    host.replaceChildren(renderScorecard({
      matchUp: dual,
      composition: compositions.National,
      home: {
        homeParticipantId: side1.participantId,
        basis: 'NONE'
      }
    }));
    expect(host.querySelector(HOME_TAG)).toBeNull();
    expect(host.querySelector(GEAR)).toBeNull();
