    await user.click(button(root, 'Alternatives'));
    await expect(root.querySelector(QUALIFY)?.textContent, root.querySelector('.tb-proposal-panel')?.textContent).toContain('7 alternates promoted');
    await user.click(root.querySelector<HTMLButtonElement>(QUALIFY)!);
    await expect(control.getEntryChanges().filter(change => change.from === ALT && change.to === DA)).toHaveLength(7);
    await expect(control.getEntryChanges().filter(change => change.from === ALT && change.fromStage === QUALIFYING)).toHaveLength(4);
